def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]

    # Treat colors with sizable connected components as real object colors.
    targets = set()
    for color in counts:
        if color == background:
            continue
        seen = set()
        largest = 0
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r, c) in seen:
                    continue
                q = [(r, c)]
                seen.add((r, c))
                size = 0
                while q:
                    y, x = q.pop()
                    size += 1
                    for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] == color and (ny, nx) not in seen):
                            seen.add((ny, nx))
                            q.append((ny, nx))
                largest = max(largest, size)
        if largest >= 4:
            targets.add(color)

    out = [row[:] for row in grid]
    noisy = {x for x in counts if x != background and x not in targets}

    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == background or value in targets:
                continue

            best = None
            # Look for a nearly solid rectangle of a target color containing this
            # stray pixel, and restore the pixel to that color.
            for color in targets:
                for r0 in range(r + 1):
                    for r1 in range(r, h):
                        if r1 - r0 + 1 < 2:
                            continue
                        for c0 in range(c + 1):
                            for c1 in range(c, w):
                                if c1 - c0 + 1 < 2:
                                    continue
                                area = (r1-r0+1) * (c1-c0+1)
                                if area > 100:
                                    continue
                                vals = [grid[y][x]
                                        for y in range(r0, r1+1)
                                        for x in range(c0, c1+1)]
                                if any(v != color and v not in noisy for v in vals):
                                    continue
                                n = sum(v == color for v in vals)
                                density = n / area
                                if n >= 3 and density >= 0.70:
                                    score = (density, n, -area)
                                    if best is None or score > best[0]:
                                        best = (score, color)
            out[r][c] = best[1] if best else background
    return out
